-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_frpm AS SELECT frpm.CDSCode AS CDSCode, frpm.`Academic Year` AS `Academic Year`, frpm.`County Code` AS `County Code`, frpm.`District Code` AS `District Code`, frpm.`School Code` AS `School Code`, frpm.`County Name` AS `County Name`, frpm.`District Name` AS `District Name`, frpm.`School Name` AS `School Name`, frpm.`District Type` AS `District Type`, frpm.`School Type` AS `School Type`, frpm.`Educational Option Type` AS `Educational Option Type`, frpm.`NSLP Provision Status` AS `NSLP Provision Status`, frpm.`Charter School (Y/N)` AS `Charter School (Y/N)`, frpm.`Charter School Number` AS `Charter School Number`, frpm.`Charter Funding Type` AS `Charter Funding Type`, frpm.IRC AS IRC, frpm.`Low Grade` AS `Low Grade`, frpm.`High Grade` AS `High Grade`, frpm.`Enrollment (K-12)` AS `Enrollment (K-12)`, frpm.`Free Meal Count (K-12)` AS `Free Meal Count (K-12)`, frpm.`Percent (%) Eligible Free (K-12)` AS `Percent (%) Eligible Free (K-12)`, frpm.`FRPM Count (K-12)` AS `FRPM Count (K-12)`, frpm.`Percent (%) Eligible FRPM (K-12)` AS `Percent (%) Eligible FRPM (K-12)`, frpm.`Enrollment (Ages 5-17)` AS `Enrollment (Ages 5-17)`, frpm.`Free Meal Count (Ages 5-17)` AS `Free Meal Count (Ages 5-17)`, frpm.`Percent (%) Eligible Free (Ages 5-17)` AS `Percent (%) Eligible Free (Ages 5-17)`, frpm.`FRPM Count (Ages 5-17)` AS `FRPM Count (Ages 5-17)`, frpm.`Percent (%) Eligible FRPM (Ages 5-17)` AS `Percent (%) Eligible FRPM (Ages 5-17)`, frpm.`2013-14 CALPADS Fall 1 Certification Status` AS `2013-14 CALPADS Fall 1 Certification Status`, schools.NCESDist AS NCESDist, schools.NCESSchool AS NCESSchool, schools.StatusType AS StatusType, schools.County AS County, schools.District AS District, schools.School AS School, schools.Street AS Street, schools.StreetAbr AS StreetAbr, schools.City AS City, schools.Zip AS Zip, schools.State AS State, schools.MailStreet AS MailStreet, schools.MailStrAbr AS MailStrAbr, schools.MailCity AS MailCity, schools.MailZip AS MailZip, schools.MailState AS MailState, schools.Phone AS Phone, schools.Ext AS Ext, schools.Website AS Website, schools.OpenDate AS OpenDate, schools.ClosedDate AS ClosedDate, schools.Charter AS Charter, schools.CharterNum AS CharterNum, schools.FundingType AS FundingType, schools.DOC AS DOC, schools.DOCType AS DOCType, schools.SOC AS SOC, schools.SOCType AS SOCType, schools.EdOpsCode AS EdOpsCode, schools.EdOpsName AS EdOpsName, schools.EILCode AS EILCode, schools.EILName AS EILName, schools.GSoffered AS GSoffered, schools.GSserved AS GSserved, schools.Virtual AS Virtual, schools.Magnet AS Magnet, schools.Latitude AS Latitude, schools.Longitude AS Longitude, schools.AdmFName1 AS AdmFName1, schools.AdmLName1 AS AdmLName1, schools.AdmEmail1 AS AdmEmail1, schools.AdmFName2 AS AdmFName2, schools.AdmLName2 AS AdmLName2, schools.AdmEmail2 AS AdmEmail2, schools.AdmFName3 AS AdmFName3, schools.AdmLName3 AS AdmLName3, schools.AdmEmail3 AS AdmEmail3, schools.LastUpdate AS LastUpdate FROM frpm LEFT JOIN schools AS schools ON frpm.CDSCode = schools.CDSCode;

